export const KIND = {"id":59,"example":{"id":"E59","kind":59,"source":"aether","statement":["Write a function `pair_check::found(const std::vector<int>& list, int first, int second)` that returns how many of the 2 values the list holds, as a value of `enum class pair_check::Found { both, one, neither }`, which the header defines.","Return `both` when the list holds both values, `one` when it holds just one of them, else `neither`.","Limits: 0 ≤ length of the list ≤ 1000."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <vector>","","namespace pair_check {","","enum class Found { both, one, neither };","","bool holds(const std::vector<int>& list, int value)","{","    for (const int item : list) {","        if (item == value) {","            return true;","        }","    }","    return false;","}","","Found found(const std::vector<int>& list, int first, int second)","{","    const bool has_first {holds(list, first)};","    const bool has_second {holds(list, second)};","    if (has_first && has_second) {","        return Found::both;","    } else if (has_first || has_second) {","        return Found::one;","    } else {","        return Found::neither;","    }","}","","}  // namespace pair_check"],"frame":[0,2,4,31],"labels":[{"at":6,"level":1,"text":"Name each possible value in an `enum class`."},{"at":8,"level":1,"text":"Write a function that gives back true at the first item that passes a test, else false."},{"at":10,"level":2,"text":"Give back true at the first item equal to the value."},{"at":15,"level":2,"text":"Give back false, since no item matched."},{"at":18,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":20,"level":2,"text":"Give back both when the list holds both values, one when it holds one, else neither."},{"at":24,"level":0,"text":"Join 2 tests with `||`, which holds when either one holds."}],"blanks":[]}},"trace":{"id":"T59","lines":["#include <iostream>","#include <print>","#include <vector>","bool has_negative(const std::vector<int>& list)","{","    for (const int item : list) {","        if (item < 0) {","            return true;","        }","    }","    return false;","}","int main()","{","    std::vector<int> list(3, 0);","    std::cin >> list[0] >> list[1] >> list[2];","    std::println(\"{}\", has_negative(list));","}"],"columns":["list","item"],"inputs":["3 -1 4\n","5 6 7\n"],"rows":[{"line":15,"values":["[0, 0, 0]",""]},{"line":16,"values":["[3, -1, 4]",""]},{"line":6,"values":["[3, -1, 4]","3"]},{"line":7,"values":["[3, -1, 4]","3"]},{"line":6,"values":["[3, -1, 4]","-1"]},{"line":7,"values":["[3, -1, 4]","-1"]},{"line":8,"values":["[3, -1, 4]","-1"]},{"line":17,"values":["[3, -1, 4]",""]}],"output":"false\n"},"traces":[],"problems":{"59.01":{"id":"59.01","kind":59,"source":"exercism","statement":["Write a function `sublist::sublist(const std::vector<int>& list_one, const std::vector<int>& list_two)` that returns how the two lists relate, as a value of `enum class List_comparison { equal, sublist, superlist, unequal }`, which you write in namespace `sublist` too.","Return `equal` when the lists hold the same values in the same order.","Else return `sublist` when the second list holds the first as a run of values next to each other, and `superlist` when the first holds the second so.","Else return `unequal`. The empty list is a run inside every list.","Limits: 0 ≤ length of each list ≤ 1000."],"examples":[{"input":"empty lists","output":""}],"tests":[{"input":"empty list within non empty list","output":""},{"input":"non empty list contains empty list","output":""},{"input":"list equals itself","output":""},{"input":"different lists","output":""},{"input":"false start","output":""},{"input":"consecutive","output":""},{"input":"sublist at start","output":""},{"input":"sublist in middle","output":""},{"input":"sublist at end","output":""},{"input":"at start of superlist","output":""},{"input":"in middle of superlist","output":""},{"input":"at end of superlist","output":""},{"input":"first list missing element from second list","output":""},{"input":"second list missing element from first list","output":""},{"input":"first list missing additional digits from second list","output":""},{"input":"order matters to a list","output":""},{"input":"same digits but different numbers","output":""}],"solution":{"lines":["#pragma once","","#include <algorithm>","#include <vector>","","namespace sublist {","","enum class List_comparison {","    equal, sublist, superlist, unequal","};","","bool contains(const std::vector<int>& list,","    const std::vector<int>& part)","{","    for (std::size_t start {0};","         start + part.size() <= list.size(); ++start) {","        const auto first {list.begin() + start};","        if (std::equal(part.begin(), part.end(), first)) {","            return true;","        }","    }","    return false;","}","","List_comparison sublist(const std::vector<int>& list_one,","    const std::vector<int>& list_two)","{","    if (list_one == list_two) {","        return List_comparison::equal;","    } else if (contains(list_two, list_one)) {","        return List_comparison::sublist;","    } else if (contains(list_one, list_two)) {","        return List_comparison::superlist;","    } else {","        return List_comparison::unequal;","    }","}","","}  // namespace sublist"],"frame":[0,2,3,5,9,38],"labels":[{"at":7,"level":1,"text":"Name each possible value in an `enum class`."},{"at":11,"level":1,"text":"Write a function that gives back true at the first item that passes a test, else false."},{"at":14,"level":2,"text":"Give back true at the first start in the list where the part follows."},{"at":21,"level":2,"text":"Give back false, since no start matched."},{"at":24,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":27,"level":2,"text":"Give back equal for equal lists, sublist when the second holds the first, superlist when the first holds the second, else unequal."}],"blanks":[{"line":8,"from":11,"to":18},{"line":11,"from":14,"to":42},{"line":17,"from":12,"to":55},{"line":21,"from":11,"to":16},{"line":24,"from":24,"to":56},{"line":27,"from":8,"to":28}]},"fn":{"slug":"sublist","commit":"8d139cb0","header":"sublist.h","name":"sublist_test.cpp","test":"#include \"sublist.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\n/*\nLists are ordered and sequential.\nhttps://en.wikipedia.org/wiki/List_%28abstract_data_type%29\n\nDepending on your language, there may need to be some translation\nto go from the JSON array to the list representation.\nThe expectation can be used to generate an expected value\nbased on your implementation (such as a constant 'EQUAL', 'SUBLIST', etc.).\n\nIf appropriate for your track, you'll need to ensure that no pair of expected\nvalues are equal. Otherwise, an implementation that always returns a constant\nvalue may falsely pass the tests. See\nhttps://github.com/exercism/xpython/issues/342\n*/\n\nCATCH_REGISTER_ENUM(sublist::List_comparison, sublist::List_comparison::equal,\n                    sublist::List_comparison::sublist,\n                    sublist::List_comparison::superlist,\n                    sublist::List_comparison::unequal)\n\nTEST_CASE(\"empty lists\", \"[97319c93-ebc5-47ab-a022-02a1980e1d29]\") {\n    sublist::List_comparison expected = sublist::List_comparison::equal;\n    REQUIRE(expected == sublist::sublist({}, {}));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"empty list within non empty list\",\n          \"[de27dbd4-df52-46fe-a336-30be58457382]\") {\n    sublist::List_comparison expected = sublist::List_comparison::sublist;\n    REQUIRE(expected == sublist::sublist({}, {1, 2, 3}));\n}\n\nTEST_CASE(\"non empty list contains empty list\",\n          \"[5487cfd1-bc7d-429f-ac6f-1177b857d4fb]\") {\n    sublist::List_comparison expected = sublist::List_comparison::superlist;\n    REQUIRE(expected == sublist::sublist({1, 2, 3}, {}));\n}\n\nTEST_CASE(\"list equals itself\", \"[1f390b47-f6b2-4a93-bc23-858ba5dda9a6]\") {\n    sublist::List_comparison expected = sublist::List_comparison::equal;\n    REQUIRE(expected == sublist::sublist({1, 2, 3}, {1, 2, 3}));\n}\n\nTEST_CASE(\"different lists\", \"[7ed2bfb2-922b-4363-ae75-f3a05e8274f5]\") {\n    sublist::List_comparison expected = sublist::List_comparison::unequal;\n    REQUIRE(expected == sublist::sublist({1, 2, 3}, {2, 3, 4}));\n}\n\nTEST_CASE(\"false start\", \"[3b8a2568-6144-4f06-b0a1-9d266b365341]\") {\n    sublist::List_comparison expected = sublist::List_comparison::sublist;\n    REQUIRE(expected == sublist::sublist({1, 2, 5}, {0, 1, 2, 3, 1, 2, 5, 6}));\n}\n\nTEST_CASE(\"consecutive\", \"[dc39ed58-6311-4814-be30-05a64bc8d9b1]\") {\n    sublist::List_comparison expected = sublist::List_comparison::sublist;\n    REQUIRE(expected == sublist::sublist({1, 1, 2}, {0, 1, 1, 1, 2, 1, 2}));\n}\n\nTEST_CASE(\"sublist at start\", \"[d1270dab-a1ce-41aa-b29d-b3257241ac26]\") {\n    sublist::List_comparison expected = sublist::List_comparison::sublist;\n    REQUIRE(expected == sublist::sublist({0, 1, 2}, {0, 1, 2, 3, 4, 5}));\n}\n\nTEST_CASE(\"sublist in middle\", \"[81f3d3f7-4f25-4ada-bcdc-897c403de1b6]\") {\n    sublist::List_comparison expected = sublist::List_comparison::sublist;\n    REQUIRE(expected == sublist::sublist({2, 3, 4}, {0, 1, 2, 3, 4, 5}));\n}\n\nTEST_CASE(\"sublist at end\", \"[43bcae1e-a9cf-470e-923e-0946e04d8fdd]\") {\n    sublist::List_comparison expected = sublist::List_comparison::sublist;\n    REQUIRE(expected == sublist::sublist({3, 4, 5}, {0, 1, 2, 3, 4, 5}));\n}\n\nTEST_CASE(\"at start of superlist\", \"[76cf99ed-0ff0-4b00-94af-4dfb43fe5caa]\") {\n    sublist::List_comparison expected = sublist::List_comparison::superlist;\n    REQUIRE(expected == sublist::sublist({0, 1, 2, 3, 4, 5}, {0, 1, 2}));\n}\n\nTEST_CASE(\"in middle of superlist\", \"[b83989ec-8bdf-4655-95aa-9f38f3e357fd]\") {\n    sublist::List_comparison expected = sublist::List_comparison::superlist;\n    REQUIRE(expected == sublist::sublist({0, 1, 2, 3, 4, 5}, {2, 3}));\n}\n\nTEST_CASE(\"at end of superlist\", \"[26f9f7c3-6cf6-4610-984a-662f71f8689b]\") {\n    sublist::List_comparison expected = sublist::List_comparison::superlist;\n    REQUIRE(expected == sublist::sublist({0, 1, 2, 3, 4, 5}, {3, 4, 5}));\n}\n\nTEST_CASE(\"first list missing element from second list\",\n          \"[0a6db763-3588-416a-8f47-76b1cedde31e]\") {\n    sublist::List_comparison expected = sublist::List_comparison::unequal;\n    REQUIRE(expected == sublist::sublist({1, 3}, {1, 2, 3}));\n}\n\nTEST_CASE(\"second list missing element from first list\",\n          \"[83ffe6d8-a445-4a3c-8795-1e51a95e65c3]\") {\n    sublist::List_comparison expected = sublist::List_comparison::unequal;\n    REQUIRE(expected == sublist::sublist({1, 2, 3}, {1, 3}));\n}\n\nTEST_CASE(\"first list missing additional digits from second list\",\n          \"[7bc76cb8-5003-49ca-bc47-cdfbe6c2bb89]\") {\n    sublist::List_comparison expected = sublist::List_comparison::unequal;\n    REQUIRE(expected == sublist::sublist({1, 2}, {1, 22}));\n}\n\nTEST_CASE(\"order matters to a list\", \"[0d7ee7c1-0347-45c8-9ef5-b88db152b30b]\") {\n    sublist::List_comparison expected = sublist::List_comparison::unequal;\n    REQUIRE(expected == sublist::sublist({1, 2, 3}, {3, 2, 1}));\n}\n\nTEST_CASE(\"same digits but different numbers\",\n          \"[5f47ce86-944e-40f9-9f31-6368aad70aa6]\") {\n    sublist::List_comparison expected = sublist::List_comparison::unequal;\n    REQUIRE(expected == sublist::sublist({1, 0, 1}, {10, 1}));\n}\n\n#endif\n","setup":["sublist::List_comparison expected = sublist::List_comparison::equal;"],"calls":[{"call":"sublist::sublist({}, {})","expected":"expected"}]}},"59.02":{"id":"59.02","kind":59,"source":"aether","statement":["Write a function `signs::mix(const std::vector<int>& list)` that returns which signs the list holds, as a value of `enum class signs::Mix { both, positive, negative, none }`, which the header defines.","Return `both` when the list holds a number above 0 and a number below 0, `positive` when it holds only numbers above 0 among those not 0, `negative` when it holds only numbers below 0 among those not 0, else `none`.","Limits: 0 ≤ length of the list ≤ 1000; -1000 ≤ each number ≤ 1000."],"examples":[{"input":"one_of_each","output":""}],"tests":[{"input":"empty_list","output":""},{"input":"only_zeros","output":""},{"input":"positive_with_zeros","output":""},{"input":"negative_only","output":""},{"input":"one_positive","output":""},{"input":"one_negative","output":""},{"input":"both_far_apart","output":""}],"solution":{"lines":["#pragma once","","#include <vector>","","namespace signs {","","enum class Mix { both, positive, negative, none };","","bool has_sign(const std::vector<int>& list, int sign)","{","    for (const int item : list) {","        if (item * sign > 0) {","            return true;","        }","    }","    return false;","}","","Mix mix(const std::vector<int>& list)","{","    const bool positive {has_sign(list, 1)};","    const bool negative {has_sign(list, -1)};","    if (positive && negative) {","        return Mix::both;","    } else if (positive) {","        return Mix::positive;","    } else if (negative) {","        return Mix::negative;","    } else {","        return Mix::none;","    }","}","","}  // namespace signs"],"frame":[0,2,4,33],"labels":[{"at":6,"level":1,"text":"Name each possible value in an `enum class`."},{"at":8,"level":1,"text":"Write a function that gives back true at the first item that passes a test, else false."},{"at":10,"level":2,"text":"Give back true at the first item whose sign is the sign given."},{"at":15,"level":2,"text":"Give back false, since no item matched."},{"at":18,"level":1,"text":"Write a function that tests each case in order and gives back the result of the first that holds."},{"at":20,"level":2,"text":"Give back both when the list holds both signs, positive or negative when it holds one, else none."}],"blanks":[{"line":6,"from":17,"to":21},{"line":8,"from":14,"to":42},{"line":11,"from":12,"to":27},{"line":15,"from":11,"to":16},{"line":18,"from":8,"to":36},{"line":22,"from":8,"to":28}]},"fn":{"slug":"signs","commit":"","header":"signs.h","name":"signs_test.cpp","test":"#include \"signs.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"one_of_each\") { REQUIRE(signs::mix({1, -2}) == signs::Mix::both); }\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"empty_list\") { REQUIRE(signs::mix({}) == signs::Mix::none); }\nTEST_CASE(\"only_zeros\") { REQUIRE(signs::mix({0, 0, 0}) == signs::Mix::none); }\nTEST_CASE(\"positive_with_zeros\") {\n    REQUIRE(signs::mix({0, 5, 0}) == signs::Mix::positive);\n}\nTEST_CASE(\"negative_only\") {\n    REQUIRE(signs::mix({-1000, -1}) == signs::Mix::negative);\n}\nTEST_CASE(\"one_positive\") { REQUIRE(signs::mix({1000}) == signs::Mix::positive); }\nTEST_CASE(\"one_negative\") { REQUIRE(signs::mix({-7}) == signs::Mix::negative); }\nTEST_CASE(\"both_far_apart\") {\n    std::vector<int> list(1000, 3);\n    list.back() = -3;\n    REQUIRE(signs::mix(list) == signs::Mix::both);\n}\n#endif\n","setup":[],"calls":[{"call":"signs::mix({1, -2})","expected":"signs::Mix::both"}]}}}}
